def reverse(head):
    prev=None; cur=head
    while cur:
        nxt=cur.next; cur.next=prev; prev=cur; cur=nxt
    return prev

def serialize(root):
    if not root: return '#,'
    return str(root.val)+','+serialize(root.left)+serialize(root.right)

class DSU:
    def __init__(self,n): self.p=[-1]*n
    def find(self,x):
        if self.p[x]<0: return x
        self.p[x]=self.find(self.p[x]); return self.p[x]
    def union(self,a,b):
        ra,rb=self.find(a),self.find(b)
        if ra==rb: return False
        if -self.p[ra]<-self.p[rb]: ra,rb=rb,ra
        self.p[ra]+=self.p[rb]; self.p[rb]=ra; return True

class HashTable:
    def __init__(self,m=101): self.m=m; self.table=[[] for _ in range(m)]
    def insert(self,k):
        h=k%self.m; lst=self.table[h];
        if k not in lst: lst.append(k)

import random
def quickselect(a,k):
    if not a: return None
    pivot=random.choice(a)
    L=[x for x in a if x<pivot]; M=[x for x in a if x==pivot]; R=[x for x in a if x>pivot]
    if k<=len(L): return quickselect(L,k)
    elif k<=len(L)+len(M): return pivot
    else: return quickselect(R,k-len(L)-len(M))

from collections import defaultdict
def build_inverted(docs):
    inv=defaultdict(list)
    for i,text in enumerate(docs):
        for w in text.split(): inv[w].append(i)
    return inv
